//! One accepted native request owns its durable pick; this store starts no native work.
use super::{
    database::{Database, Requirements},
    decimal::{Decimal, ticket},
    *,
};
use orch_db::queries::{pool_choices as saved, pools as written};
use orch_types::{Json, new_id};

/// Reference-only native source identity, generated by the accepted consumer, never an HTTP intent.
pub struct ChoiceRequest {
    pub id: Id,
    pub target: Target,
    pub source: Json,
}
/// Factual selected identity. Native source, Use/lending and capacity are rechecked at first effect.
/// Deliberately has no wire serializer or reusable admission.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Choice {
    pub id: Id,
    pub leaf: Option<Leaf>,
    pub path: Vec<Hop>,
    pub reason: Option<String>,
}
fn bad(message: impl Into<String>) -> EngineError {
    EngineError::unreadable(message)
}
fn amount(value: &str) -> Result<Decimal, EngineError> {
    Decimal::parse(value).ok_or_else(|| bad("the stored policy weight is not a decimal"))
}
fn increment(value: &mut i64) -> Result<i64, EngineError> {
    let current = *value;
    *value = value
        .checked_add(1)
        .ok_or_else(|| bad("the choice detail exceeds its integer representation"))?;
    Ok(current)
}
async fn current_membership(
    conn: &mut orch_db::Conn,
    target: &Target,
    leaf: &Leaf,
    path: &[Hop],
) -> Result<bool, EngineError> {
    match target {
        Target::Single { resource } => return Ok(path.is_empty() && resource == leaf),
        Target::Pool { id, kind } => {
            if path.first().is_none_or(|hop| hop.pool_id != *id) || leaf.kind() != *kind {
                return Ok(false);
            }
        }
    }
    for (index, hop) in path.iter().enumerate() {
        let Some(pool) = written::get(conn, hop.pool_id)
            .await?
            .filter(|row| row.deleted_at.is_none() && row.kind == leaf.kind().as_str())
        else {
            return Ok(false);
        };
        if pool.definition.get("enabled").and_then(Json::as_bool) != Some(true) {
            return Ok(false);
        }
        let depth =
            orch_settings::get::<u64>(conn, orch_settings::Place::Pool(pool.id), "pools.max_depth")
                .await
                .map_err(|error| bad(error.to_string()))?
                .ok_or_else(|| bad("the pool depth has no default"))?;
        if u64::try_from(path.len() - index).map_err(|error| bad(error.to_string()))? > depth {
            return Ok(false);
        }
        let Some(member) = written::member(conn, pool.id, hop.member_id)
            .await?
            .filter(|member| member.enabled)
        else {
            return Ok(false);
        };
        let rule: MemberRule = serde_json::from_value(member.rule)?;
        if let Some(next) = path.get(index + 1) {
            if !matches!(rule,MemberRule::Pool{id,kind}if id==next.pool_id&&kind==leaf.kind()) {
                return Ok(false);
            }
        } else if !written::rule_contains(conn, pool.org_id, &rule, leaf).await? {
            return Ok(false);
        }
    }
    Ok(true)
}
impl<R: Requirements> Database<'_, R> {
    /// Reserve only inside the consumer's accepted transaction. Commit before dispatch, and retain
    /// the original native request/attempt id on replay. A preview only walks Resolver.
    pub async fn reserve(mut self, request: &ChoiceRequest) -> Result<Choice, EngineError> {
        if self.requirements.inspect_only() {
            return Err(bad("inspection cannot reserve a pool choice"));
        }
        let expected = match &request.target {
            Target::Single { resource } => resource.kind(),
            Target::Pool { kind, .. } => *kind,
        };
        request.target.validate(expected).map_err(bad)?;
        let target = serde_json::to_value(&request.target)?;
        let stored = saved::begin(
            self.conn,
            request.id,
            self.principal.user(),
            &request.source,
            &target,
            self.principal.now().get(),
        )
        .await?;
        if stored.actor_id != self.principal.user()
            || stored.source != request.source
            || stored.target != target
        {
            return Err(bad("the choice belongs to another accepted native source"));
        }
        if stored.state != "building" {
            let leaf: Option<Leaf> = stored.leaf.map(serde_json::from_value).transpose()?;
            let path: Vec<Hop> =
                serde_json::from_value(stored.path.unwrap_or_else(|| serde_json::json!([])))?;
            let mut reason = stored.reason;
            if let Target::Pool { id, .. } = &request.target {
                let pool = self.pool(*id).await?;
                if pool
                    .as_ref()
                    .is_none_or(|pool| !pool.definition.enabled || pool.reason.is_some())
                {
                    reason = Some("pool_unavailable".into());
                }
            }
            if let Some(leaf) = &leaf {
                if !current_membership(self.conn, &request.target, leaf, &path).await? {
                    reason = Some("member_removed".into());
                } else if reason.is_none() {
                    reason = self
                        .requirements
                        .reason(self.conn, self.principal, leaf, &path)
                        .await?;
                }
            }
            return Ok(Choice {
                id: request.id,
                leaf: if reason.is_none() { leaf } else { None },
                path,
                reason,
            });
        }
        let at = match &request.target {
            Target::Pool { id, .. } => orch_settings::Place::Pool(*id),
            _ => orch_settings::Place::System,
        };
        let batch = orch_settings::get::<i64>(self.conn, at, "pools.read_batch_size")
            .await
            .map_err(|error| bad(error.to_string()))?
            .ok_or_else(|| bad("the pool read batch has no default"))?;
        let mut walk = Resolver::new(self, &request.target, expected).await?;
        let mut stack: Vec<(Id, Id)> = Vec::new();
        let mut root = None;
        let mut ordinal = 0i64;
        let mut direct = None;
        while let Some(event) = walk.next().await? {
            let sequence = increment(&mut ordinal)?;
            let source = walk.source_mut();
            match event {
                Event::Enter { pool, path } => {
                    let id = new_id();
                    if root.is_none() {
                        root = Some(id);
                    }
                    let edge = path.last();
                    let policy = serde_json::to_value(&pool.definition.policy)?;
                    saved::node(
                        source.conn,
                        request.id,
                        &saved::Node {
                            id,
                            pool: pool.id,
                            parent: stack.last().map(|node| node.0),
                            member: edge.map(|hop| hop.member_id),
                            priority: edge.map_or(0, |hop| hop.priority),
                            weight: edge.map_or("1", |hop| hop.weight.as_str()),
                            ordinal: sequence,
                            policy: &policy,
                            revision: pool.revision,
                            definition: &serde_json::to_value(&pool.definition)?,
                            defaults: &serde_json::to_value(&pool.defaults)?,
                        },
                    )
                    .await?;
                    stack.push((id, pool.id));
                }
                Event::Candidate { leaf, path, reason } => {
                    if let Some((parent, _)) = stack.last() {
                        let edge = path
                            .last()
                            .ok_or_else(|| bad("the pooled leaf lost its membership source"))?;
                        saved::member(
                            source.conn,
                            request.id,
                            &saved::Member {
                                ordinal: sequence,
                                parent: *parent,
                                member: edge.member_id,
                                priority: edge.priority,
                                weight: &edge.weight,
                                leaf: &serde_json::to_value(&leaf)?,
                                path: &serde_json::to_value(&path)?,
                                reason: reason.as_deref(),
                            },
                            &stack.iter().map(|node| node.0).collect::<Vec<_>>(),
                        )
                        .await?;
                    } else {
                        direct = Some((leaf, path, reason));
                    }
                }
                Event::Skipped { path, reason } => {
                    saved::skipped(
                        source.conn,
                        request.id,
                        sequence,
                        &serde_json::to_value(path)?,
                        &reason,
                    )
                    .await?
                }
                Event::Leave { pool_id, .. } => {
                    if stack.pop().is_none_or(|node| node.1 != pool_id) {
                        return Err(bad("the native choice walk lost a policy boundary"));
                    }
                }
            }
        }
        let mut source = walk.into_source();
        saved::lock_policies(source.conn, request.id).await?;
        let mut after = None;
        loop {
            let rows = saved::observed(source.conn, request.id, after, batch).await?;
            if rows.is_empty() {
                break;
            }
            for row in &rows {
                let Some(current) = source.pool(row.pool_id).await? else {
                    return Err(bad("the pool changed before reservation"));
                };
                if current.reason.is_some()
                    || serde_json::to_value(&current.definition)? != row.definition
                    || serde_json::to_value(&current.defaults)? != row.defaults
                {
                    return Err(bad("the pool changed before reservation"));
                }
            }
            after = rows.last().map(|row| row.ordinal);
        }
        let chosen = if let Some(root) = root {
            select(&mut source, request.id, root).await?
        } else {
            direct
        };
        let Some((leaf, path, reason)) = chosen else {
            saved::finish(
                source.conn,
                request.id,
                None,
                &serde_json::json!([]),
                Some("pool_exhausted"),
                source.principal.now().get(),
            )
            .await?;
            return Ok(Choice {
                id: request.id,
                leaf: None,
                path: vec![],
                reason: Some("pool_exhausted".into()),
            });
        };
        let eligible = reason.is_none()
            && current_membership(source.conn, &request.target, &leaf, &path).await?;
        let reason = if eligible {
            source
                .requirements
                .reason(source.conn, source.principal, &leaf, &path)
                .await?
        } else {
            reason.or_else(|| Some("member_removed".into()))
        };
        let accepted = reason.is_none();
        let encoded = accepted.then(|| serde_json::to_value(&leaf)).transpose()?;
        saved::finish(
            source.conn,
            request.id,
            encoded.as_ref(),
            &serde_json::to_value(&path)?,
            reason.as_deref(),
            source.principal.now().get(),
        )
        .await?;
        Ok(Choice {
            id: request.id,
            leaf: accepted.then_some(leaf),
            path,
            reason,
        })
    }
}
async fn select<R: Requirements>(
    source: &mut Database<'_, R>,
    choice: Id,
    mut node: Id,
) -> Result<Option<(Leaf, Vec<Hop>, Option<String>)>, EngineError> {
    loop {
        let policy = saved::policy(source.conn, choice, node).await?;
        let policy_value: Option<orch_provider_contract::pools::Policy> =
            serde_json::from_value(policy.policy)?;
        let policy_value = policy_value.ok_or_else(|| bad("the enabled pool has no policy"))?;
        if matches!(
            policy_value,
            orch_provider_contract::pools::Policy::LeastCost
                | orch_provider_contract::pools::Policy::LeastLoaded { .. }
        ) {
            return Err(bad(
                "the score policy needs its native request measurements",
            ));
        }
        let batch: usize = orch_settings::get(
            source.conn,
            orch_settings::Place::Pool(policy.pool_id),
            "pools.read_batch_size",
        )
        .await
        .map_err(|error| bad(error.to_string()))?
        .ok_or_else(|| bad("the pool read batch has no default"))?;
        let batch = i64::try_from(batch).map_err(|error| bad(error.to_string()))?;
        let mut after = None;
        let mut total = Decimal::default();
        let mut winner: Option<(saved::Edge, Decimal, Option<Id>)> = None;
        if policy_value == orch_provider_contract::pools::Policy::RoundRobin {
            saved::reset_ineligible(
                source.conn,
                choice,
                node,
                policy.pool_id,
                source.principal.now().get(),
            )
            .await?;
        }
        loop {
            let edges = saved::edges(source.conn, choice, node, after, batch).await?;
            if edges.is_empty() {
                break;
            }
            for edge in &edges {
                let weight = amount(&edge.weight)?;
                if !weight.positive() {
                    return Err(bad("a pool weight must be positive"));
                }
                total = total.add(&weight);
                match policy_value {
                    orch_provider_contract::pools::Policy::Ordered => {
                        if winner.is_none() {
                            winner = Some((edge.clone(), Decimal::default(), None));
                        }
                    }
                    orch_provider_contract::pools::Policy::RoundRobin => {
                        let state = saved::rotation(
                            source.conn,
                            policy.pool_id,
                            &edge.identity,
                            &edge.weight,
                            source.principal.now().get(),
                        )
                        .await?;
                        let current = if amount(&state.weight)? == weight {
                            amount(&state.current_weight)?
                        } else {
                            Decimal::default()
                        }
                        .add(&weight);
                        saved::rotate(
                            source.conn,
                            state.id,
                            &edge.weight,
                            &current.to_string(),
                            source.principal.now().get(),
                        )
                        .await?;
                        if winner.as_ref().is_none_or(|(_, best, _)| current > *best) {
                            winner = Some((edge.clone(), current, Some(state.id)));
                        }
                    }
                    _ => {}
                }
            }
            after = edges.last().map(|edge| edge.ordinal);
        }
        if !matches!(
            policy_value,
            orch_provider_contract::pools::Policy::Ordered
                | orch_provider_contract::pools::Policy::RoundRobin
        ) {
            let mut draw = ticket(&total, || rand::random_range(0u8..10))
                .ok_or_else(|| bad("the pool has no positive eligible weight"))?;
            let mut after = None;
            'pick: loop {
                let edges = saved::edges(source.conn, choice, node, after, batch).await?;
                if edges.is_empty() {
                    break;
                }
                for edge in &edges {
                    let weight = amount(&edge.weight)?;
                    if draw < weight {
                        winner = Some((edge.clone(), Decimal::default(), None));
                        break 'pick;
                    }
                    draw = draw.sub(&weight);
                }
                after = edges.last().map(|edge| edge.ordinal);
            }
        }
        let Some((edge, current, state)) = winner else {
            return Ok(None);
        };
        if let Some(state) = state {
            saved::rotate(
                source.conn,
                state,
                &edge.weight,
                &current.sub(&total).to_string(),
                source.principal.now().get(),
            )
            .await?;
        }
        if let Some(child) = edge.child {
            node = child;
            continue;
        }
        let leaf = serde_json::from_value(
            edge.leaf
                .ok_or_else(|| bad("the chosen contribution has no leaf"))?,
        )?;
        let path = serde_json::from_value(
            edge.path
                .ok_or_else(|| bad("the chosen contribution has no membership path"))?,
        )?;
        return Ok(Some((leaf, path, None)));
    }
}
